// ─── Unfiltered Truth Oracle — 44-card relationship deck (text-only) ───
export const UNFILTERED_TRUTH_ORACLE = [
  { id: 'ut-01', name: 'The Ghost', meaning: `They're here but not really here — showing up just enough to keep you hoping but not enough to actually show up. Ghosting isn't always disappearing. Sometimes it's staying just present enough to keep the door open while they figure out if they actually want to walk through it. The question isn't why they keep vanishing. The question is: what do YOU want to do with someone who keeps making you wonder?`, keywords: ['avoidance', 'inconsistency', 'fear of commitment', 'limbo'] },
  { id: 'ut-02', name: 'Sovereignty', meaning: `You've been giving this person your power in small ways — waiting for their text to set the mood of your day, making decisions based on what they might think, dimming yourself to make them comfortable. This card is a direct invitation to take it back. Your sovereignty is not negotiable. Your peace, your time, your emotional energy — these are not bargaining chips in someone else's story. Reclaim them. Fully. Now.`, keywords: ['personal power', 'self-authority', 'independence', 'boundaries'] },
  { id: 'ut-03', name: 'The Breadcrumbs', meaning: `You are being kept alive on the bare minimum — a text here, a reaction there, just enough to keep you invested but not enough to actually feed you. Breadcrumbs are not a meal. They are a strategy, whether conscious or not, to keep you available without committing. You deserve someone who brings the whole loaf. Stop starving and calling it a relationship.`, keywords: ['minimal effort', 'stringing along', 'inconsistency', 'low investment'] },
  { id: 'ut-04', name: 'The Mirror', meaning: `What frustrates you most about this person may be reflecting something you haven't faced in yourself — a fear of vulnerability, an old wound that says you're unworthy of consistency, a pattern you keep choosing because it feels familiar even when it hurts. Look honestly. The irritation is data. The mirror doesn't lie, even when what it shows is uncomfortable.`, keywords: ['self-reflection', 'projection', 'inner work', 'patterns'] },
  { id: 'ut-05', name: 'The Red Flag You Rationalized', meaning: `You saw it. You knew. And then you found twelve reasons why it was fine, why they didn't mean it that way, why it was your fault, why you were being too sensitive. This card is not here to shame you — it's here to name the thing you've been naming for someone else for too long. The flag was red. You are allowed to trust what you saw.`, keywords: ['denial', 'rationalization', 'gaslighting', 'clarity'] },
  { id: 'ut-06', name: 'The Situationship', meaning: `You have all the intimacy of a relationship and none of the commitment. You share their bed, their secrets, their Sunday mornings — and you have no idea where you stand. This in-between place was never meant to be permanent housing. At some point you have to decide: are you willing to name what you actually want, even if naming it means losing what you have?`, keywords: ['undefined relationship', 'ambiguity', 'avoidance', 'truth-telling'] },
  { id: 'ut-07', name: 'The Slow Fade', meaning: `Nothing dramatic happened. The conversations just got shorter. The response times got longer. The plans stopped materializing. The slow fade is one of the cruelest exits because it leaves you wondering if you imagined the whole thing. You didn't. And you deserve an ending that has actual words in it — even if those words are hard.`, keywords: ['withdrawal', 'avoidance', 'ending', 'closure'] },
  { id: 'ut-08', name: 'Their Potential vs. Their Pattern', meaning: `You are in love with who they could be, not who they are consistently showing up as. Potential is a beautiful, seductive thing — and it is not a foundation. Who someone is on their best day is not a promise of who they'll be on the ordinary ones. What is their pattern? That is your answer.`, keywords: ['projection', 'wishful thinking', 'patterns', 'reality check'] },
  { id: 'ut-09', name: 'The Almost Relationship', meaning: `You were close. You felt it. Something real was building — and then it stopped, or changed, or was never quite defined. Almost relationships carry a specific kind of grief because there's no clear event to mourn. You just… end up without the thing you thought you were building. That grief is valid. Grieve it. Then make space for something that doesn't make you wonder.`, keywords: ['grief', 'unclear endings', 'ambiguity', 'unfinished'] },
  { id: 'ut-10', name: 'Reciprocity', meaning: `Look at who initiates. Who follows up. Who makes the effort to show up when it's inconvenient. Who remembers the small things. Is the energy matched? Love is not supposed to be a one-person job. If you consistently feel like you're doing more, it's because you are. That's information. Use it.`, keywords: ['balance', 'mutual effort', 'energy exchange', 'one-sided'] },
  { id: 'ut-11', name: 'The Rebound', meaning: `Someone is here — but they are using your warmth to thaw out from someone else's cold. That doesn't make them a villain. It makes them human and not ready. The danger is that rebounds feel like love in the early stages, because the intensity is real — it just isn't necessarily about you. Are you the destination or the waystation?`, keywords: ['unhealed', 'transitional', 'readiness', 'not about you'] },
  { id: 'ut-12', name: 'Love Bombing', meaning: `It came in fast and it came in big — the attention, the affection, the declarations. It felt like finally. But intensity at the start of a connection is not the same as depth. Real love builds over time with consistent, humble action. What arrived in a flood can leave the same way. Ask yourself: is this person showing up consistently, or performing for the highlight reel?`, keywords: ['intensity', 'manipulation', 'pace', 'red flags'] },
  { id: 'ut-13', name: 'The Anxious Attachment Loop', meaning: `You reach out, then pull back to check if they'll chase. They don't chase fast enough, so the anxiety spikes. You interpret their normal behavior as rejection and react from that place. They pull back. You reach more. It's a cycle, and it is exhausting for both of you. The loop only breaks when you interrupt your end of it — not by trying harder, but by getting grounded in yourself.`, keywords: ['attachment patterns', 'anxiety', 'self-regulation', 'cycle-breaking'] },
  { id: 'ut-14', name: 'The Test', meaning: `You are testing them — sometimes deliberately, sometimes not. Pulling away to see if they follow. Being vague to see if they'll push for clarity. Starting arguments to see how they handle conflict. Tests are a trauma response, not a connection strategy. The person meant for you shouldn't have to pass a series of trials you haven't told them about. Let them in, or let them go.`, keywords: ['fear of intimacy', 'self-protection', 'vulnerability', 'trust'] },
  { id: 'ut-15', name: 'Avoidant Energy', meaning: `They want connection — in theory. In practice, the moment things get real, they create distance. It might look like being "too busy," or suddenly finding faults, or pulling back right when things start to feel good. Avoidance is not a character flaw; it's usually a wound. But a wound that someone refuses to look at cannot be loved away. You cannot out-love someone's unwillingness to be present.`, keywords: ['avoidant attachment', 'distance', 'intimacy avoidance', 'patterns'] },
  { id: 'ut-16', name: 'The Apology That Changed Nothing', meaning: `They said sorry. They may have even meant it in the moment. But the behavior continued. An apology without behavioral change is just words dressed up as accountability. It's important to notice: do you keep accepting apologies for the same things? Because eventually the apology stops being the issue. The acceptance is.`, keywords: ['accountability', 'patterns', 'change', 'self-worth'] },
  { id: 'ut-17', name: 'The Hot and Cold', meaning: `Intense one week, distant the next. Present and warm, then suddenly cold for no visible reason. The hot and cold dynamic is one of the most destabilizing experiences in connection because your nervous system never gets to relax. You're always preparing for the shift. That is not intimacy. That is survival. You deserve a temperature you can live in.`, keywords: ['inconsistency', 'emotional regulation', 'nervous system', 'stability'] },
  { id: 'ut-18', name: 'Projection', meaning: `Someone is putting something on you that belongs to them — accusing you of the very things they're doing, suspicious of behaviors that mirror their own, assigning motives to you that live in their own history. It's disorienting, because you keep trying to defend yourself against a portrait that isn't you. Stop defending. You know who you are. The painting is theirs.`, keywords: ['projection', 'gaslighting', 'self-knowing', 'others\' wounds'] },
  { id: 'ut-19', name: 'The Jealousy Play', meaning: `Someone is using your feelings for them as leverage — mentioning others to gauge your reaction, creating triangles, making you feel like you have competition you need to rise to. Real love does not require you to perform for an audience. If you feel like you're constantly competing, it's because someone is making you compete. That is a choice they are making. Not a situation you have to play in.`, keywords: ['manipulation', 'insecurity', 'triangulation', 'competition'] },
  { id: 'ut-20', name: 'The Comfort Zone', meaning: `You've been together long enough that comfort replaced intention. The relationship isn't bad — it's just... quiet. The effort that built what you have stopped once you had it. Something needs to be consciously revived here — not with grand gestures, but with the small, deliberate choices to keep choosing each other. Is that something you're both willing to do?`, keywords: ['complacency', 'intentionality', 'long-term love', 'reinvestment'] },
  { id: 'ut-21', name: 'The Walls They Built', meaning: `They want love. They just don't fully believe they can have it, or that it will stay, or that they're worth it when things get hard. The walls aren't about you — they were built long before you arrived. You can be patient. You can be gentle. But you cannot dismantle someone else's walls for them. That is their work. The question is how long you're willing to knock.`, keywords: ['emotional walls', 'past wounds', 'patience limits', 'their work'] },
  { id: 'ut-22', name: 'Emotional Unavailability', meaning: `They are present in body and absent in soul. You can feel the distance even when they're right next to you. The conversations stay surface-level no matter how deep you try to go. Emotional unavailability is not permanent — but it is not something you can fix by being more loving, more patient, more understanding. They have to choose to show up. Have they?`, keywords: ['emotional absence', 'surface-level connection', 'unhealed', 'readiness'] },
  { id: 'ut-23', name: 'The Unsaid Thing', meaning: `There is something neither of you has said out loud yet — a truth that's been living in the silences, in the careful conversations, in the things you almost say and then swallow. This card is asking you to name it. Not to burn everything down, but because unnamed things have enormous power over the shape of a relationship. Say the thing. See what happens.`, keywords: ['communication', 'courage', 'truth-telling', 'unspoken tension'] },
  { id: 'ut-24', name: 'The Sacrifice That Wasn\'t Reciprocated', meaning: `You gave something up — time, energy, a part of yourself — and it wasn't met with equal care on their side. That sacrifice deserves acknowledgment, even if it's just from you to you. You cannot keep donating parts of your life to someone who doesn't notice the cost. Generosity is beautiful. Depletion is not.`, keywords: ['self-sacrifice', 'one-sided', 'resentment', 'self-care'] },
  { id: 'ut-25', name: 'The Fear of Loss', meaning: `You're making choices from the fear of losing them, not from the clarity of what you actually want. Fear-based love stays in situations past their expiration date. It says yes when it means no. It makes itself smaller. Fear of loss is real and understandable — but it is not a strategy. What would you choose if you weren't afraid of losing them?`, keywords: ['fear', 'scarcity mindset', 'choice', 'clarity'] },
  { id: 'ut-26', name: 'Worth the Wait', meaning: `Good things take time. This particular connection may be asking you for patience — not blind patience, but the kind rooted in genuine evidence that something real is being built. Are there consistent signs of care, growth, and intention between you? Then trust the slower pace. Real love doesn't always arrive on your timeline.`, keywords: ['patience', 'trust', 'timing', 'evidence-based hope'] },
  { id: 'ut-27', name: 'The Grand Gesture Trap', meaning: `They showed up with something big — a declaration, a surprise, an impressive move — right when you were about to pull away. And it worked. It bought more time. But notice: the grand gesture arrived right at the edge of your limit. That timing is not coincidence. Love should not require a performance to keep you. Watch what happens after the gesture fades.`, keywords: ['manipulation', 'patterns', 'grand gestures', 'consistency'] },
  { id: 'ut-28', name: 'The Comparison', meaning: `You're being compared — to an ex, to an ideal, to someone else they see as the standard. Or you're doing the comparing. Either way, this card says: stop. Nobody wins in comparison. You are not a consolation prize, and you are not a judge. Every person and every connection is its own thing. Measure this relationship only against what you need and what you deserve.`, keywords: ['comparison', 'self-worth', 'fairness', 'uniqueness'] },
  { id: 'ut-29', name: 'The Gut Feeling', meaning: `Your body has been trying to tell you something for a while now. That tight feeling in your chest when you see their name. The way your shoulders tense instead of relax when you hear from them. The quiet dread that lives just under the hope. Your gut is not dramatic. It is not broken. It is the oldest, wisest part of you, and it is trying to get your attention. Listen.`, keywords: ['intuition', 'body wisdom', 'knowing', 'trust yourself'] },
  { id: 'ut-30', name: 'The Misalignment', meaning: `You want different things — and both of you know it. Maybe one wants a family and the other doesn't. Maybe one is ready to commit and the other needs years of freedom. Maybe the values that seemed similar have revealed themselves to be fundamentally different. Misalignment is not a failure of love. It is a reality of timing, life stage, and direction. Love is sometimes not enough.`, keywords: ['incompatibility', 'life path', 'values', 'hard truths'] },
  { id: 'ut-31', name: 'The Return', meaning: `They're back — or you're considering going back. Before you do anything, get honest: what has actually changed? Not what has been promised. Not what feels possible in this hopeful, charged moment. What has concretely, demonstrably shifted in the dynamic, the behavior, the underlying issue that caused the break? If the answer is "nothing," returning is not a reunion. It's a repeat.`, keywords: ['reconciliation', 'returning', 'what has changed', 'patterns'] },
  { id: 'ut-32', name: 'The Friendship Foundation', meaning: `The romantic feeling may have complicated, faded, or shifted — but underneath it, there is something genuinely real: a friendship, a care, a history that matters. This card asks you to be honest about what form this relationship is actually meant to take in your life. Not every love story is a romance. Some of the deepest loves of our lives are the ones that eventually find their truest shape.`, keywords: ['friendship', 'connection type', 'honest redefinition', 'care'] },
  { id: 'ut-33', name: 'Vulnerability', meaning: `You have been managing yourself in this relationship — carefully editing what you share, keeping the raw, unfiltered version of yourself behind the curtain. The person who loves the curated version doesn't fully know you yet. Real intimacy lives on the other side of the risk of being truly seen. You don't have to share everything at once. But you do have to let them see you, eventually.`, keywords: ['vulnerability', 'authenticity', 'intimacy', 'being seen'] },
  { id: 'ut-34', name: 'The Boundary That Keeps Getting Crossed', meaning: `You've said it. Maybe more than once. And it keeps happening — maybe slightly differently, maybe with a good explanation, but it keeps happening. A boundary that is consistently ignored is a message about how someone views your limits. Take it seriously. Not with anger, but with clarity. What you allow continues.`, keywords: ['boundaries', 'self-respect', 'patterns', 'what you allow'] },
  { id: 'ut-35', name: 'The Healing Connection', meaning: `This person arrived in your life at a time when you needed something to soften — to open up what you had closed off, to remind you that safety in love is possible. This may be exactly what it is: a healing connection. Not necessarily forever, but genuinely significant. Honor what is being healed here, even if the relationship ultimately takes a different form than you hoped.`, keywords: ['healing', 'purpose', 'temporary but real', 'gratitude'] },
  { id: 'ut-36', name: 'The Karmic Pattern', meaning: `You have been here before — not with this person, but in this dynamic. The same emotional landscape, the same push-pull, the same feeling of almost. Karmic patterns repeat until they're learned. What is this situation teaching you that all the previous versions of it have been trying to teach you? The lesson is not about them. It never was.`, keywords: ['karmic patterns', 'repetition', 'soul lessons', 'growth'] },
  { id: 'ut-37', name: 'The Ultimatum', meaning: `Something has reached its edge. A decision needs to be made — by you, by them, or by both. Ultimatums get a bad reputation, but clarity is not a weapon. Knowing what you need and being honest about the limits of your capacity to wait is not manipulation. It is self-knowledge in action. What do you actually need from this situation? And are you willing to hold that line?`, keywords: ['decision point', 'clarity', 'limits', 'self-knowledge'] },
  { id: 'ut-38', name: 'Space That Isn\'t Distance', meaning: `Someone needs room to breathe — it doesn't mean they're pulling away or losing interest. It means they are a person who needs space to process, to restore, to return to themselves before they can fully return to you. Can you hold that without making it mean something it doesn't? Can you give space generously, rather than fearfully?`, keywords: ['space', 'introversion', 'trust', 'not abandonment'] },
  { id: 'ut-39', name: 'Choosing Yourself', meaning: `There comes a moment when the most loving thing you can do — for both of you — is to choose yourself. Not dramatically. Not as a punishment. But with the quiet, firm knowledge that you cannot keep reducing yourself to fit into someone else's story. You are the main character in your own life. Act like it. Choose yourself first and let everything rearrange around that.`, keywords: ['self-first', 'self-love', 'main character energy', 'boundaries'] },
  { id: 'ut-40', name: 'The Unhealed Wound', meaning: `Something they did — or something that was done to them long before you arrived — is running the show right now. Old pain shows up in new relationships wearing present-tense costumes. This card asks: is the wound theirs to heal, or have you been absorbing the impact of someone else's unfinished emotional work? You can have compassion and still have limits.`, keywords: ['trauma', 'healing', 'compassion', 'limits'] },
  { id: 'ut-41', name: 'The Long Game', meaning: `This is a slow build. It doesn't have the intensity of the early stages — it has something quieter and more durable: consistent presence, genuine care, a person who shows up without being asked. The long game isn't romantic in a cinematic way. It is romantic in the way that actually matters: reliably, honestly, over time. Don't mistake steadiness for boring.`, keywords: ['long-term love', 'consistency', 'quiet depth', 'steadiness'] },
  { id: 'ut-42', name: 'The Permission You Keep Waiting For', meaning: `You are waiting for someone — them, a sign, the universe, your past self — to give you permission to leave, to stay, to speak, to love, to let go. That permission was always yours to grant. Nobody is coming to release you. Nobody can give you the signal that it's finally okay. The authority over your own life has always lived in you. Use it.`, keywords: ['permission', 'self-authority', 'decision-making', 'empowerment'] },
  { id: 'ut-43', name: 'The Love That Wasn\'t Enough', meaning: `You loved them. Truly. And it still didn't work. That is one of the hardest truths love teaches us: that love can be real and still not be enough. It doesn't mean you failed. It doesn't mean love is meaningless. It means that love requires timing, readiness, compatibility, and mutual will — and sometimes one of those pieces is missing. You did not love wrong. The pieces just didn't all fit.`, keywords: ['grief', 'love without success', 'acceptance', 'honoring what was real'] },
  { id: 'ut-44', name: 'What You Deserve', meaning: `You have spent so long adjusting to less that you've started to mistake it for normal. Someone who is consistently present. Someone who communicates honestly even when it's uncomfortable. Someone who chooses you not just when it's convenient, but on the Tuesday afternoons when nothing is particularly exciting. That is not a fantasy. That is a standard. Remember what you actually deserve.`, keywords: ['self-worth', 'standards', 'what love looks like', 'raising the bar'] },
];

